paragraph.math:
$$\begin{array}{l}
  {\frac{b - a}{b - a}\left\lbrack {f\left( x_{1} \right) \cdot \frac{1}{n} + f\left( x_{2} \right) \cdot \frac{1}{n} + \ldots + f\left( x_{n} \right) \cdot \frac{1}{n}} \right\rbrack = \frac{1}{b - a}\left\lbrack {f\left( x_{1} \right) \cdot \frac{b - a}{n} + f\left( x_{2} \right) \cdot \frac{b - a}{n} + \ldots + f\left( x_{n} \right) \cdot \frac{b - a}{n}} \right\rbrack} \\
  {\phantom{\frac{b - a}{b - a}\left\lbrack {f\left( x_{1} \right) \cdot \frac{1}{n} + f\left( x_{2} \right) \cdot \frac{1}{n} + \ldots + f\left( x_{n} \right) \cdot \frac{1}{n}} \right\rbrack} = \frac{1}{b - a}\left\lbrack {f\left( x_{1} \right)\Delta x + f\left( x_{2} \right)\Delta x + \ldots + f\left( x_{n} \right)\Delta x} \right\rbrack}
  \end{array}$$

$$\begin{array}{l}
  {\lim\limits_{n\rightarrow\infty}\left\lbrack \frac{f\left( x_{1} \right) + f\left( x_{2} \right) + \cdot \cdot \cdot + f\left( x_{n} \right)}{n} \right\rbrack = \frac{1}{b - a}\lim\limits_{n\rightarrow\infty}\left\lbrack {f\left( x_{1} \right)\Delta x + f\left( x_{2} \right)\Delta x + \cdot \cdot \cdot + f\left( x_{n} \right)\Delta x} \right\rbrack} \\
  {\phantom{\lim\limits_{n\rightarrow\infty}\left\lbrack \frac{f\left( x_{1} \right) + f\left( x_{2} \right) + \cdot \cdot \cdot + f\left( x_{n} \right)}{n} \right\rbrack} = \frac{1}{b - a}{\int_{a}^{b}{f(x)}}dx}
  \end{array}$$
